     1	import { EmptyObject } from "./obj.ts";
     2	import { hasProp } from "./object.ts";
     3	
     4	export function parseURLEncodedBody(body: string): unknown {
     5	  return collectEntries(new URLSearchParams(body).entries());
     6	}
     7	
     8	export function parseFormData(form: FormData): unknown {
     9	  return collectEntries(form.entries());
    10	}
    11	
    12	// Collect key/value entries into an object, keeping repeated keys as arrays
    13	// (e.g. multi-selects or `foo=1&foo=2`) instead of dropping earlier values.
    14	function collectEntries(entries: IterableIterator<[string, unknown]>): unknown {
    15	  const parsed: Record<string, any> = new EmptyObject();
    16	  for (const [key, value] of entries) {
    17	    if (hasProp(parsed, key)) {
    18	      if (!Array.isArray(parsed[key])) {
    19	        parsed[key] = [parsed[key]];
    20	      }
    21	      parsed[key].push(value);
    22	    } else {
    23	      parsed[key] = value;
    24	    }
    25	  }
    26	  return parsed as unknown;
    27	}

